"""Apply locally tested source patch. The gzip transport is not runtime code.
Input/output hashes and an exact path set prevent replacing newer work.
The resulting source diff remains visible as normal repository files.
"""
from pathlib import Path
import base64,gzip,hashlib,subprocess,json
ROOT=Path(__file__).resolve().parents[1]
CHANGES=json.loads('{"app-src/main_windows.go":{"before":"c110cecc0406830c10c45912ff5b8ab1834c98263ebbf7221cb264e8911b8195","after":"859fbdd7d3be15e720c68f9ad69eb3fcb23d71d4fffc7efd7482db2de0db27a3"},"app-src/prepared_resource.go":{"before":null,"after":"d53cd79b8f4f70bf7bb3f4a8383195969f37fde4e96720f963f8735e8c6b275d"},"app-src/prepared_resource_test.go":{"before":null,"after":"8d37e890ce2a0f1d8065ba7d1048a48a0354b3913c577893dab0247f066b1404"},"app-src/startup_trace_windows.go":{"before":"9794bbc291e470f3fe1c93e261557e590fe8877ad76030fd4281ed1d92ce7a3e","after":"c33b7194668c8a1c901a76fa6649664240d5990b13d0c25a381939daec1cfca7"},"app-src/sumatra_document_windows.go":{"before":"2e1f2f091f710d7f39e1cd61d240aa1b3168dc6448de20589380e4aa80b1d8fa","after":"ff882c6774a70b069d81fe52a02de0d8affb7bbb1baee7f85b64f054c983f9c7"},"app-src/sumatra_pending_windows_test.go":{"before":null,"after":"e7489368fbb8fe42983f0b8592b7f5b31ccf407c4b5b3d3a1b4f360562144716"},"app-src/sumatra_preview_windows.go":{"before":"7337a449a24b97c54d6cccb2176590f10879bf2e4d7811cb73b3097e6d458269","after":"c72a651b6c5ad029d2a1a9f82f358db8ca1909cd5955961cf8fe99c28dd706d6"},"app-src/sumatra_startup_windows.go":{"before":null,"after":"0debccd368b3918f36e310bf77f55f1f7286d69cd3a37d560353d1a2534179a1"},"tools/flowdev-dcm/config/checks.json":{"before":"ef204c5b8a56d9f678ea37d2376e1cccddfbeeaef6767cc9322ab4d4e1ce19a1","after":"bdfba19a6dda6d97843609057ddccb01dd8a033ce647215225ad0f4a9aa47371"},"tools/test-ui-sumatra-lifecycle.ps1":{"before":"e30da1dbfedc1c6f51aaed363f6369a40ec43705fb8c5d05e89d063923b352a2","after":"1d4a065058f3a778ff4c65c94c09f3dda7063b701bdb4f101cf19cd3e4f46376"}}')
PAYLOAD=''
patch=gzip.decompress(base64.b64decode(PAYLOAD))
assert hashlib.sha256(patch).hexdigest()=='32aadc95ca3dc4ff2fde9641ee375ee800b35433e68afac9934689a40bc4b7cb'
def digest(p): return hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else None
if all(digest(ROOT/n)==v['after'] for n,v in CHANGES.items()):
 print('Exact async startup patch already applied.')
else:
 for name,v in CHANGES.items(): assert digest(ROOT/name)==v['before'],(name,'source changed; reconcile before applying')
 subprocess.run(['git','apply','--check','-'],input=patch,cwd=ROOT,check=True)
 subprocess.run(['git','apply','-'],input=patch,cwd=ROOT,check=True)
 for name,v in CHANGES.items(): assert digest(ROOT/name)==v['after'],(name,'output mismatch')
 print('Applied and verified',len(CHANGES),'source/test files.')
